SELECT 276, '하바나 클럽 스페셜', 'Havana Club Special', '럼', '스탠다드',
       '보통', 14, 16,
       '하이볼', '여름', NULL, '하바나 클럽 럼 45ml (1½ oz), 라임 ½개, 민트 6~8장, 설탕 1 tsp, 탄산수 적당량(약 90ml)', '민트의 청량함을 살려 구성한 onz 오리지널 칵테일.
하바나 클럽 럼, 라임, 민트를 써서 톡 쏘는 탄산, 은은한 단맛과 산뜻한 산미가 어우러지는 맛. 사진 속 색과 가니시를 기준으로 재료를 정함.',
       'http://onz-cocktail.kr/uploads/cocktails/onz_cocktail_Havana_Club_Special.webp', 'http://onz-cocktail.kr/uploads/glasses/onz_glasstype_highball.webp'
WHERE NOT EXISTS (SELECT 1 FROM cocktail WHERE id = 276);

INSERT INTO cocktail_step (cocktail_id, step_order, instruction, source)
SELECT 276, 1, '하이볼에 라임 ½개, 민트 6~8장을 넣고 머들러로 가볍게 으깬다.', 'AUTO'
WHERE NOT EXISTS (SELECT 1 FROM cocktail_step WHERE cocktail_id = 276 AND step_order = 1);

